const crypto=require('node:crypto');
const S=require('./subjects.cjs');const standardCards=[...require('./question-bank.json').cards,...require('./course-bank.json').cards];const visualCards=[...require('./visual-bank.json').cards,...require('./course-visual-bank.json').cards];const cards=[...standardCards,...visualCards];
const byId=new Map(cards.map(c=>[c.id,c]));
function shuffle(items){const out=[...items];for(let i=out.length-1;i>0;i--){const j=crypto.randomInt(i+1);[out[i],out[j]]=[out[j],out[i]]}return out}
function createPlan({unit,scope,speed,includeVisual=false,subject='termicas'}){const config=S.get(subject);if(!config)throw Error('Materia inválida');const units=unit===-1?Array.from({length:subject==='termicas'?(scope==='completo'?14:10):config.topics.length},(_,i)=>i):[unit];const groups=shuffle(units).map(u=>shuffle(standardCards.filter(c=>(c.subject||'termicas')===subject&&c.unit===u&&(scope==='completo'||!c.extended))));const ids=[];for(let row=0;row<Math.max(...groups.map(g=>g.length));row++)for(const group of groups)if(group[row])ids.push(group[row].id);const diagrams=includeVisual?shuffle(visualCards.filter(c=>(c.subject||'termicas')===subject&&units.includes(c.unit))):[];diagrams.forEach((c,i)=>ids.splice(Math.min(i*3,ids.length),0,c.id));if(!ids.length)throw Error('No hay preguntas preparadas para este tema.');return {version:1,subject,includeVisual,ids,index:0,cycle:1,hintUsed:false,unit,scope,speed,limit:unit===-1?units.length+diagrams.length:Math.min(8+diagrams.length,ids.length),expires:Date.now()+12*60*60*1000}}
function signPlan(plan,key){const payload=Buffer.from(JSON.stringify(plan)).toString('base64url');return payload+'.'+crypto.createHmac('sha256',key).update('oral-plan-v1:'+payload).digest('base64url')}
function readPlan(token,key){if(typeof token!=='string'||token.length>16000)throw Error('Plan inválido');const [payload,sig]=token.split('.');if(!payload||!sig)throw Error('Plan inválido');const expected=crypto.createHmac('sha256',key).update('oral-plan-v1:'+payload).digest();const provided=Buffer.from(sig,'base64url');if(provided.length!==expected.length||!crypto.timingSafeEqual(provided,expected))throw Error('Plan inválido');const plan=JSON.parse(Buffer.from(payload,'base64url').toString('utf8'));if(plan.version!==1||plan.expires<Date.now()||!Array.isArray(plan.ids)||plan.ids.length>150||!plan.ids.length||plan.ids.some(id=>!byId.has(id))||!Number.isInteger(plan.index)||plan.index<0||plan.index>=plan.ids.length)throw Error('Plan vencido o inválido');return plan}
function current(plan){const card=byId.get(plan.ids[plan.index]);return {...card,...card[plan.speed]}}
function advance(plan){const next={...plan,index:plan.index+1,hintUsed:false};if(next.index>=next.ids.length){next.index=0;next.cycle++}return next}
function visual(plan){const c=current(plan);return c.visual?{...c.visual,targets:c.targets}:null}
function progress(plan){return {position:plan.index+1,total:plan.ids.length,limit:plan.limit,cycle:plan.cycle,prepared:cards.filter(c=>(c.subject||'termicas')===(plan.subject||'termicas')).length,variants:cards.filter(c=>(c.subject||'termicas')===(plan.subject||'termicas')).length*3}}
function initial(plan,key){const card=current(plan);const question=card.bookPrompt||card.question;return {speech:question,question,visual:visual(plan),feedbackSpeech:'',hintUsed:false,transcript:'',feedback:'',strengths:[],improvements:[],score:0,finished:false,reference:card.sources.map(s=>s.title).join(' · ')||'Programa de la asignatura / explicación general',omissions:[],betterAnswer:'',criteria:[],sourceIds:card.sources.map(s=>s.id),evaluated:false,sources:card.sources,planToken:signPlan(plan,key),planProgress:progress(plan),speed:plan.speed}}
module.exports={visual,createPlan,signPlan,readPlan,current,advance,progress,initial};
